ruleBookInfo.tocUrl:
option.-1@value
@js: 
so = java.ajax(baseUrl.replace(/book/,"chapter"));
java.setContent(so);
var id = baseUrl.match(/book\/(.*?)\.html/)[1];
java.put("id",id);
var pages = result;
java.put("page",pages);
result = source.key + "/index.php?action=loadChapterPage" + "," + JSON.stringify({
  "body": `id=${id}&page=1`,
  "method": "POST"
});

ruleToc.nextTocUrl:
@js: result = []
id = java.get("id");
pages = java.get("page");
for (let i = 2 ; i <= pages ; i++) {
option = source.key + "/index.php?action=loadChapterPage" + "," + JSON.stringify({
  "body": `id=${id}&page=${i}`,
  "method": "POST"
});
result.push(option);
}
result;

